// F839 (RFC 9110 sec 15.4): on 301 and 302 only POST becomes GET, on 303 every
// method except HEAD becomes GET, and 307 and 308 never change the method.
func TestDefaultApiClient_RedirectMethodRewriting(t *testing.T) {
	t.Parallel()
	cases := []struct {
		status     int
		method     string
		wantMethod string
		wantBody   string
	}{
		{301, "POST", "GET", ""},
		{302, "POST", "GET", ""},
		{301, "PUT", "PUT", "payload"},
		{302, "PUT", "PUT", "payload"},
		{301, "PATCH", "PATCH", "payload"},
		{302, "DELETE", "DELETE", "payload"},
		{303, "PUT", "GET", ""},
		{303, "DELETE", "GET", ""},
		{303, "POST", "GET", ""},
		{303, "HEAD", "HEAD", ""},
		{307, "PUT", "PUT", "payload"},
		{308, "DELETE", "DELETE", "payload"},
		{307, "POST", "POST", "payload"},
	}
	for _, tc := range cases {
		t.Run(fmt.Sprintf("%d_%s", tc.status, tc.method), func(t *testing.T) {
			t.Parallel()
			var gotMethod, gotBody string
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if r.URL.Path == "/start" {
					http.Redirect(w, r, "/end", tc.status)
					return
				}
				b, _ := io.ReadAll(r.Body)
				gotMethod, gotBody = r.Method, string(b)
				w.WriteHeader(200)
			}))
			defer server.Close()
			transport, buildErr := NewTransportOptionsBuilder().FollowRedirects(true).MaxRedirects(5).Build()
			if buildErr != nil {
				t.Fatal(buildErr)
			}
			client := NewDefaultApiClient(transport)
			var body any
			if tc.method != "HEAD" {
				body = []byte("payload")
			}
			resp, err := client.SendRequest(tc.method, server.URL+"/start",
				map[string]string{"Content-Type": "text/plain"}, body)
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if resp.StatusCode != 200 {
				t.Fatalf("expected 200 after the redirect, got %d", resp.StatusCode)
			}
			if gotMethod != tc.wantMethod {
				t.Errorf("expected method %s, got %s", tc.wantMethod, gotMethod)
			}
			if gotBody != tc.wantBody {
				t.Errorf("expected body %q, got %q", tc.wantBody, gotBody)
			}
		})
	}
}

// T-new-3: multipart bodies must be replayed across 307 redirects per
// RFC 7231 §6.4.7 / RFC 7538. Regression test: ensure the follow-up
// request after a 307 still carries the multipart form parts.
func TestBhvRetries012_DefaultApiClient_MultipartBodyReplayedOn307Redirect(t *testing.T) {
	t.Parallel()
	transport, buildErr := NewTransportOptionsBuilder().
		FollowRedirects(true).
		MaxRedirects(5).
		Build()
	if buildErr != nil {
		t.Fatal(buildErr)
	}
	client := NewDefaultApiClient(transport)
	headers := map[string]string{
		"Content-Type": "multipart/form-data; boundary=test-boundary",
	}
	body := []byte("--test-boundary\r\n" +
		"Content-Disposition: form-data; name=\"description\"\r\n\r\n" +
		"hello\r\n" +
		"--test-boundary\r\n" +
		"Content-Disposition: form-data; name=\"file\"; filename=\"file\"\r\n" +
		"Content-Type: application/octet-stream\r\n\r\n" +
		"file-content-bytes\r\n" +
		"--test-boundary--\r\n")
	// chasm echoes the replayed multipart body in the envelope; 200 is
	// returned only when the multipart body arrives intact at the
	// redirect target.
	resp, err := client.SendRequest("POST", chasmHTTPURL+"/test/redirect/307-multipart", headers, body)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if resp.StatusCode != 200 {
		t.Fatalf("expected status 200 after 307 redirect, got %d", resp.StatusCode)
	}
	var parsed map[string]any
	if err := json.Unmarshal([]byte(resp.Body), &parsed); err != nil {
		t.Fatalf("invalid json body: %v", err)
	}
	if parsed["method"] != "POST" {
		t.Errorf("expected method POST after 307, got %v", parsed["method"])
	}
	// chasm has no "replayed" flag; assert the body was replayed by
	// checking the echoed body is non-empty (the multipart payload).
	if b, _ := parsed["body"].(string); b == "" {
		t.Error("expected non-empty echoed body indicating multipart replay")
	}
}

