func TestBhvTransport071_DefaultApiClient_OneTimeoutBoundsEveryPhaseOfTheExchange(t *testing.T) {
	t.Parallel()
	release := make(chan struct{})
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case <-release:
		case <-r.Context().Done():
		}
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()
	defer close(release)

	timeout := 200
	transport, err := NewTransportOptionsBuilder().Timeout(&timeout).MaxRetries(0).Build()
	if err != nil {
		t.Fatal(err)
	}
	_, err = NewDefaultApiClient(transport).SendRequest("GET", server.URL+"/slow", map[string]string{}, nil)
	var timeoutErr *pkgerrors.NetworkTimeoutError
	if !errors.As(err, &timeoutErr) {
		t.Fatalf("expected the single timeout to end the slow response, got %T: %v", err, err)
	}
}

func TestBhvTransport072_DefaultApiClient_ExpiredDeadlineIsATimeoutButAClosedPortIsNot(t *testing.T) {
	t.Parallel()
	release := make(chan struct{})
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		select {
		case <-release:
		case <-r.Context().Done():
		}
	}))
	defer server.Close()
	defer close(release)

	timeout := 200
	transport, err := NewTransportOptionsBuilder().Timeout(&timeout).MaxRetries(0).Build()
	if err != nil {
		t.Fatal(err)
	}
	_, err = NewDefaultApiClient(transport).SendRequest("POST", server.URL+"/slow", map[string]string{}, []byte("payload"))
	var timeoutErr *pkgerrors.NetworkTimeoutError
	if !errors.As(err, &timeoutErr) {
		t.Fatalf("expected *NetworkTimeoutError for an expired deadline, got %T: %v", err, err)
	}

	closed := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	closedURL := closed.URL
	closed.Close()
	_, err = NewDefaultApiClient(nil).SendRequest("GET", closedURL+"/gone", map[string]string{}, nil)
	var netErr *pkgerrors.NetworkError
	if !errors.As(err, &netErr) {
		t.Fatalf("expected *NetworkError for a refused connection, got %T: %v", err, err)
	}
	if errors.As(err, &timeoutErr) {
		t.Errorf("an unrelated connection failure must not be a timeout, got %v", err)
	}
}

func TestBhvTransport073_DefaultApiClient_CorruptCompressedBodyRaisesApiError(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Encoding", "gzip")
		w.Header().Set("Content-Type", "text/plain")
		_, _ = w.Write([]byte("definitely not gzip"))
	}))
	defer server.Close()

	resp, err := NewDefaultApiClient(nil).SendRequest("GET", server.URL+"/corrupt", map[string]string{}, nil)
	var apiErr *pkgerrors.ApiError
	if !errors.As(err, &apiErr) {
		t.Fatalf("expected *ApiError for a corrupt gzip body, got %T: %v", err, err)
	}
	if apiErr.StatusCode() != http.StatusOK {
		t.Errorf("expected the response status 200 on the error, got %d", apiErr.StatusCode())
	}
	if resp != nil {
		t.Errorf("expected no response with the raw bytes, got %q", resp.Body)
	}
}

