func TestBhvTransport075_DefaultApiClient_ZstdFrameWithoutDeclaredSizeIsDecodedFully(t *testing.T) {
	t.Parallel()
	payload := strings.Repeat("a", 4<<20)
	var encoded bytes.Buffer
	writer, err := zstd.NewWriter(&encoded)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := writer.Write([]byte(payload)); err != nil {
		t.Fatal(err)
	}
	if err := writer.Close(); err != nil {
		t.Fatal(err)
	}
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Encoding", "zstd")
		w.Header().Set("Content-Type", "text/plain")
		_, _ = w.Write(encoded.Bytes())
	}))
	defer server.Close()

	resp, err := NewDefaultApiClient(nil).SendRequest("GET", server.URL+"/zstd", map[string]string{}, nil)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(resp.Body) != len(payload) {
		t.Errorf("expected the whole %d-byte payload, got %d bytes", len(payload), len(resp.Body))
	}
}

func TestBhvTransport082_DefaultApiClient_DefaultAndTimeoutOnlyClientsComplete(t *testing.T) {
	t.Parallel()
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("ok"))
	}))
	defer server.Close()

	timeout := 5000
	timed, err := NewTransportOptionsBuilder().Timeout(&timeout).Build()
	if err != nil {
		t.Fatal(err)
	}
	for name, client := range map[string]*DefaultApiClient{
		"default":      NewDefaultApiClient(nil),
		"timeout only": NewDefaultApiClient(timed),
	} {
		resp, err := client.SendRequest("GET", server.URL+"/ok", map[string]string{}, nil)
		if err != nil {
			t.Errorf("%s: unexpected error: %v", name, err)
			continue
		}
		if resp.StatusCode != http.StatusOK || resp.Body != "ok" {
			t.Errorf("%s: expected 200 with body ok, got %d %q", name, resp.StatusCode, resp.Body)
		}
	}
}

// With no credential configured, a request is sent with no Authorization header and is not refused.
func TestBhvAuth021_DefaultApiClient_RequestWithNoCredentialHasNoAuthorizationHeader(t *testing.T) {
	t.Parallel()
	seen := make(chan string, 1)
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		seen <- r.Header.Get("Authorization")
		w.WriteHeader(http.StatusOK)
	}))
	defer server.Close()

	resp, err := NewDefaultApiClient(nil).SendRequest("GET", server.URL+"/open", map[string]string{}, nil)
	if err != nil {
		t.Fatalf("expected the request to be sent, got %v", err)
	}
	if resp.StatusCode != http.StatusOK {
		t.Errorf("expected status 200, got %d", resp.StatusCode)
	}
	if got := <-seen; got != "" {
		t.Errorf("expected no Authorization header, got %q", got)
	}
}
